els.checkoutForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  if (!cart.length) return showSummary("購物車目前是空的，請先加入固定商品。");
  const id = quoteId();
  const formData = { name: $("#orderName").value.trim(), contact: $("#orderContact").value.trim(), payment: $("#paymentMethod").value, delivery: $("#deliveryMethod").value, note: $("#orderNote").value.trim() };
  const message = buildCartMessage(formData, id);
  showSummary(message);
  const estimate = cartEstimate();
  const result = await saveOrder({
    quoteId: id, type: "固定商品", customer: formData.name, contact: formData.contact,
    payment: formData.payment, delivery: formData.delivery, note: formData.note, message,
    subtotal: estimate.subtotal, discount: estimate.discount, shipping: estimate.shippingTwd,
    total: estimate.total, coupon: activeCoupon?.code || "",
    memberToken: memberSession?.token || "",
    items: cart.map((item) => ({ id: item.id, name: item.name, variant: item.selectedVariant, quantity: item.quantity, price: item.price, weight: item.weight, category: item.category, status: item.status, sourceUrl: item.sourceUrl, image: item.image })),
  });
  if (!result.synced) showSummary(`${message}\n\n注意：${result.error}。請務必點下方 LINE 按鈕把訂單傳給客服，才算完成送單。`);
  else showSummary(`${message}\n\n已成功送出訂單。請保存訂單編號，可在網站查詢進度。`);
});

els.specialType.addEventListener("change", () => { document.body.dataset.requestType = els.specialType.value; });

els.specialForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const id = quoteId();
  const message = ["瑤光代購 代訂詢問", `報價編號：${id}`, `需求類型：${els.specialType.value}`, `姓名：${$("#specialName").value.trim()}`, `聯絡方式：${$("#specialContact").value.trim()}`, `店家或場所：${$("#venueName").value.trim() || "未填"}`, `活動或商品：${$("#requestName").value.trim() || "未填"}`, `網址：${$("#specialLink").value.trim() || "未提供"}`, `日期：${$("#specialDate").value || "未指定"}`, `時間：${$("#specialTime").value || "未指定"}`, `人數：${$("#peopleCount").value || "未指定"}`, `數量：${$("#itemQuantity").value || "未指定"}`, `預算：${$("#specialBudget").value.trim() || "未指定"}`, `需求內容：${$("#specialDetails").value.trim()}`].join("\n");
  showSummary(message);
  const result = await saveOrder({ quoteId: id, type: els.specialType.value, customer: $("#specialName").value.trim(), contact: $("#specialContact").value.trim(), memberToken: memberSession?.token || "", message });
  if (!result.synced) showSummary(`${message}\n\n注意：${result.error}。請點下方 LINE 按鈕把詢問傳給客服。`);
  else showSummary(`${message}\n\n詢問已成功送出，請保存編號。`);
});

els.lookupForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const keyword = els.lookupQuoteId.value.trim().toUpperCase();
  els.lookupResult.hidden = false;
  els.lookupResult.innerHTML = "<strong>查詢中...</strong>";
  try {
    const result = await apiRequest("lookup", { quoteId: keyword }, "GET");
    renderLookup(result.order);
  } catch (error) {
    const order = orders.find((item) => item.quoteId.toUpperCase() === keyword);
    if (order) renderLookup(order);
    else els.lookupResult.innerHTML = `<strong>查詢失敗</strong><p>${error.message}</p>`;
  }
});

